  setTimeout(async () => {
    await bridge.learnTradePattern({
      name: 'Neural Convergence',
      confidence: 85,
      pnl: 247.50,
      indicators: { rsi: 45, macd: 'bullish' },
      executed_at: new Date().toISOString()
    });
  }, 5000);
});

module.exports = bridge;

